1084  rnp_result_t
  1085  write_pgp_keys(pgp_key_sequence_t *keys, pgp_dest_t *dst, bool armor)
  1086  {
  1087      pgp_dest_t   armdst = {0};
  1088      rnp_result_t ret = RNP_ERROR_GENERIC;
  1089
  1090      if (armor) {
  1091          pgp_armored_msg_t       msgtype = PGP_ARMORED_PUBLIC_KEY;
  1092          pgp_transferable_key_t *fkey = (pgp_transferable_key_t *) list_front(keys->keys);
  1093          if (fkey && is_secret_key_pkt(fkey->key.tag)) {
  1094              msgtype = PGP_ARMORED_SECRET_KEY;
  1095          }
  1096
  1097          if ((ret = init_armored_dst(&armdst, dst, msgtype))) {
  1098              return ret;
  1099          }
  1100          dst = &armdst;
  1101      }
  1102
  1103      for (list_item *li = list_front(keys->keys); li; li = list_next(li)) {
  1104          pgp_transferable_key_t *key = (pgp_transferable_key_t *) li;
  1105
  1106          /* main key */
  1107          if (!stream_write_key(&key->key, dst)) {
  1108              ret = RNP_ERROR_WRITE;
  1109              goto finish;
  1110          }
  1111          /* revocation signatures */
  1112          if (!write_pgp_signatures(key->signatures, dst)) {
  1113              ret = RNP_ERROR_WRITE;
  1114              goto finish;
  1115          }
  1116          /* user ids/attrs and signatures */
  1117          for (list_item *li = list_front(key->userids); li; li = list_next(li)) {
  1118              pgp_transferable_userid_t *uid = (pgp_transferable_userid_t *) li;
  1119
  1120              if (!stream_write_userid(&uid->uid, dst) ||
  1121                  !write_pgp_signatures(uid->signatures, dst)) {
  1122                  ret = RNP_ERROR_WRITE;
  1123                  goto finish;
  1124              }
  1125          }
  1126          /* subkeys with signatures */
  1127          for (list_item *li = list_front(key->subkeys); li; li = list_next(li)) {
  1128              pgp_transferable_subkey_t *skey = (pgp_transferable_subkey_t *) li;
  1129
  1130              if (!stream_write_key(&skey->subkey, dst) ||
  1131                  !write_pgp_signatures(skey->signatures, dst)) {
  1132                  ret = RNP_ERROR_WRITE;
  1133                  goto finish;
  1134              }
  1135          }
  1136      }
  1137
  1138      ret = RNP_SUCCESS;
  1139
  1140  finish:
  1141      if (armor) {
  1142          dst_close(&armdst, ret);
  1143      }
  1144
  1145      return ret;
  1146  }
