  1148  rnp_result_t
  1149  write_pgp_key(pgp_transferable_key_t *key, pgp_dest_t *dst, bool armor)
  1150  {
  1151      pgp_key_sequence_t keys = {0};
  1152      rnp_result_t       ret = RNP_ERROR_GENERIC;
  1153
  1154      if (!list_append(&keys.keys, key, sizeof(*key))) {
  1155          return RNP_ERROR_OUT_OF_MEMORY;
  1156      }
  1157
  1158      ret = write_pgp_keys(&keys, dst, armor);
  1159      list_destroy(&keys.keys);
  1160      return ret;
